args.command:
node --input-type=module -e "
import { parseTask } from './src/parse.js';
import { compare } from './src/compare.js';
import { runOrder } from './src/scheduler.js';

const t = parseTask({ id: 'a', priority: ' 10 ' });
console.log('parseTask output priority:', JSON.stringify(t.priority), 'typeof:', typeof t.priority);

// Compare with raw strings as parseTask currently returns them
console.log('compare string 2 vs 10:', compare({id:'a',priority:'2'}, {id:'b',priority:'10'}));
console.log('compare string 2 vs 1:', compare({id:'a',priority:'2'}, {id:'c',priority:'1'}));

// What runOrder actually produces today
console.log('runOrder today:', JSON.stringify(runOrder([
  {id:'a',priority:'2'},{id:'b',priority:'10'},{id:'c',priority:'1'}
])));

// Compare with numbers (what the spec says compare receives)
console.log('compare number 2 vs 10:', compare({id:'a',priority:2}, {id:'b',priority:10}));
console.log('compare number 2 vs 1:', compare({id:'a',priority:2}, {id:'c',priority:1}));
"

